fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"

    val oneSecondNs = 1_000_000_000L
    val denominator = oneSecondNs / exposureTimeNs

    if (denominator >= 1) {
        val commonSpeeds = listOf(1, 2, 4, 8, 15, 30, 60, 125, 250, 500, 1000, 2000, 4000, 8000, 16000)
        val closest = commonSpeeds.minByOrNull { Math.abs(it - denominator) } ?: denominator.toInt()
        return "1/${closest}s"
    }

    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds == seconds.toLong().toDouble()) {
        "${seconds.toLong()}s"
    } else {
        "${"%.1f".format(seconds).trimEnd('0').trimEnd('.')}s"
    }
}

