def _is_attacked(board, r, c, by_white):
    """Check if square (r, c) is attacked by the side 'by_white'."""

    # Knight attacks
    for dr, dc in _KNIGHT_DELTAS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 8 and 0 <= nc < 8:
            p = board[nr][nc]
            if p == ('N' if by_white else 'n'):
                return True

    # King attacks
    for dr, dc in _KING_DELTAS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 8 and 0 <= nc < 8:
            p = board[nr][nc]
            if p == ('K' if by_white else 'k'):
                return True

    # Sliding piece attacks
    # Rook/Queen directions (straight)
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        while 0 <= nr < 8 and 0 <= nc < 8:
            p = board[nr][nc]
            if p != '.':
                if p in ('R', 'Q') and by_white:
                    return True
                if p in ('r', 'q') and not by_white:
                    return True
                break
            nr += dr
            nc += dc

    # Bishop/Queen directions (diagonal)
    for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
        nr, nc = r + dr, c + dc
        while 0 <= nr < 8 and 0 <= nc < 8:
            p = board[nr][nc]
            if p != '.':
                if p in ('B', 'Q') and by_white:
                    return True
                if p in ('b', 'q') and not by_white:
                    return True
                break
            nr += dr
            nc += dc

    # Pawn attacks
    pawn = 'P' if by_white else 'p'
    pawn_dir = -1 if by_white else 1
    for dc in (-1, 1):
        nr, nc = r + pawn_dir, c + dc
        if 0 <= nr < 8 and 0 <= nc < 8:
            if board[nr][nc] == pawn:
                return True

    return False


