def _update_castling(castling: str, uci_move: str, white_to_move: bool) -> str:
    """Update castling rights after a move."""
    base = uci_move[:4]
    fc = ord(base[0]) - ord('a')
    fr = 8 - int(base[1])
    tc = ord(base[2]) - ord('a')
    tr = 8 - int(base[3])

    # King moves remove all castling for that side
    if fr == 7 and fc == 4 and white_to_move:
        castling = castling.replace('K', '').replace('Q', '')
    elif fr == 0 and fc == 4 and not white_to_move:
        castling = castling.replace('k', '').replace('q', '')

    # Rook moves remove castling for that corner
    if fr == 7 and fc == 7:
        castling = castling.replace('K', '')
    elif fr == 7 and fc == 0:
        castling = castling.replace('Q', '')
    elif fr == 0 and fc == 7:
        castling = castling.replace('k', '')
    elif fr == 0 and fc == 0:
        castling = castling.replace('q', '')

    # If a rook is captured on a corner, remove that side's castling
    if tr == 7 and tc == 7:
        castling = castling.replace('K', '')
    elif tr == 7 and tc == 0:
        castling = castling.replace('Q', '')
    elif tr == 0 and tc == 7:
        castling = castling.replace('k', '')
    elif tr == 0 and tc == 0:
        castling = castling.replace('q', '')

    return castling if castling else '-'
